DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertAdmins` ()   BEGIN
    DECLARE i INT DEFAULT 2;
    DECLARE first_names TEXT DEFAULT 'James,Michael,Robert,David,William,Richard,Joseph,Thomas,Charles,Christopher,Daniel,Matthew,Anthony,Mark,Donald,Steven,Paul,Andrew,Joshua,Kenneth,Kevin,Brian,George,Edward,Ronald,Timothy,Jason,Jeffrey,Ryan,Jacob';
    DECLARE last_names TEXT DEFAULT 'Smith,Johnson,Williams,Brown,Jones,Garcia,Miller,Davis,Rodriguez,Martinez,Hernandez,Lopez,Gonzalez,Wilson,Anderson,Thomas,Taylor,Moore,Jackson,Martin,Lee,Perez,Thompson,White,Harris,Sanchez,Clark,Ramirez,Lewis,Robinson';
    DECLARE fname VARCHAR(50);
    DECLARE lname VARCHAR(50);
    DECLARE dept_id INT;
    DECLARE desig_id INT;
    DECLARE comp_id INT;
    DECLARE salary_amt DECIMAL(10,2);
    
    WHILE i <= 500 DO
        SET fname = SUBSTRING_INDEX(SUBSTRING_INDEX(first_names, ',', ((i - 1) MOD 30) + 1), ',', -1);
        SET lname = SUBSTRING_INDEX(SUBSTRING_INDEX(last_names, ',', (i MOD 30) + 1), ',', -1);
        SET dept_id = IF(RAND() < 0.9, ((i - 1) MOD 500) + 1, NULL);
        SET desig_id = IF(RAND() < 0.9, ((i - 1) MOD 500) + 1, NULL);
        SET comp_id = ((i - 1) MOD 500) + 1;
        SET salary_amt = ROUND(50000 + (RAND() * 150000), 2);
        
        INSERT INTO admins (adminID, firstName, lastName, email, password, departmentID, designationID, companyID, salary)
        VALUES (
            i,
            fname,
            lname,
            CONCAT(LOWER(SUBSTRING(fname, 1, 1)), LOWER(lname), i, '@company', comp_id, '.com'),
            '$2y$12$uuelc/4POlVAlJ19dUKtpu/MxGAS9pYf41X5Pk.3zz4LXYH1SLAMy', -- bcrypt hash
            dept_id,
            desig_id,
            comp_id,
            salary_amt
        );
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertAttendance` ()   BEGIN
    DECLARE i INT DEFAULT 4;
    DECLARE emp_id INT;
    DECLARE sched_date DATE;
    DECLARE clock_in_time TIMESTAMP;
    DECLARE clock_out_time TIMESTAMP;
    DECLARE total_hrs DECIMAL(5,2);
    DECLARE start_hour INT;
    DECLARE end_hour INT;
    
    WHILE i <= 500 DO
        SET emp_id = ((i - 1) MOD 500) + 1;
        SET sched_date = DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 90) DAY);
        SET start_hour = 7 + FLOOR(RAND() * 3); -- 7-9 AM
        SET end_hour = 15 + FLOOR(RAND() * 4); -- 3-6 PM
        
        SET clock_in_time = CONCAT(sched_date, ' ', LPAD(start_hour, 2, '0'), ':', LPAD(FLOOR(RAND() * 60), 2, '0'), ':00');
        SET clock_out_time = CONCAT(sched_date, ' ', LPAD(end_hour, 2, '0'), ':', LPAD(FLOOR(RAND() * 60), 2, '0'), ':00');
        SET total_hrs = ROUND(TIMESTAMPDIFF(MINUTE, clock_in_time, clock_out_time) / 60, 2);
        
        INSERT INTO attendance (attendanceID, employeeID, scheduleDate, clockIN, clockOut, totalHours)
        VALUES (i, emp_id, sched_date, clock_in_time, clock_out_time, total_hrs);
        
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertCompanies` ()   BEGIN
    DECLARE i INT DEFAULT 4;
    DECLARE company_names TEXT DEFAULT 'Tech Solutions,Global Ventures,Innovation Labs,Prime Industries,Future Systems,Digital Dynamics,Smart Technologies,Enterprise Solutions,Peak Performance,Vertex Group,Summit Corp,Horizon Enterprises,Zenith Solutions,Alpha Tech,Omega Systems,Delta Industries,Sigma Group,Phoenix Rising,Titan Corp,Stellar Systems';
    DECLARE company_name VARCHAR(50);
    
    WHILE i <= 500 DO
        SET company_name = CONCAT(
            SUBSTRING_INDEX(SUBSTRING_INDEX(company_names, ',', ((i - 1) MOD 20) + 1), ',', -1),
            ' ', 
            FLOOR((i-1)/20) + 1
        );
        
        INSERT INTO companies (companyID, companyName)
        VALUES (i, company_name);
        
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertDepartments` ()   BEGIN
    DECLARE i INT DEFAULT 9;
    DECLARE dept_names TEXT DEFAULT 'Construction,Sales,Marketing,Finance,Human Resources,IT Support,Operations,Research & Development,Customer Service,Quality Assurance';
    DECLARE dept_name VARCHAR(50);
    DECLARE comp_id INT;
    
    WHILE i <= 500 DO
        SET dept_name = SUBSTRING_INDEX(SUBSTRING_INDEX(dept_names, ',', ((i - 1) MOD 10) + 1), ',', -1);
        SET comp_id = ((i - 1) MOD 500) + 1;
        
        INSERT INTO departments (departmentID, departmentName, companyID)
        VALUES (i, dept_name, comp_id);
        
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertDesignations` ()   BEGIN
    DECLARE i INT DEFAULT 4;
    DECLARE designation_names TEXT DEFAULT 'Manager,Senior Developer,Junior Developer,Team Lead,Business Analyst,Data Analyst,Project Manager,Product Manager,Software Engineer,Quality Assurance,System Administrator,Database Admin,UI/UX Designer,DevOps Engineer,Security Analyst,Network Engineer,HR Specialist,Financial Analyst,Marketing Manager,Sales Executive';
    DECLARE desig_name VARCHAR(50);
    
    WHILE i <= 500 DO
        SET desig_name = CONCAT(
            SUBSTRING_INDEX(SUBSTRING_INDEX(designation_names, ',', ((i - 1) MOD 20) + 1), ',', -1),
            IF(i > 20, CONCAT(' Level ', FLOOR((i-1)/20) + 1), '')
        );
        
        INSERT INTO designations (designationID, designationName)
        VALUES (i, desig_name);
        
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertEmployees` ()   BEGIN
    DECLARE i INT DEFAULT 4;
    DECLARE first_names TEXT DEFAULT 'Emma,Olivia,Ava,Isabella,Sophia,Mia,Charlotte,Amelia,Harper,Evelyn,Abigail,Emily,Elizabeth,Sofia,Avery,Ella,Scarlett,Grace,Chloe,Victoria,Riley,Aria,Lily,Aubrey,Zoey,Penelope,Lillian,Addison,Layla,Natalie';
    DECLARE last_names TEXT DEFAULT 'Anderson,Baker,Carter,Davis,Evans,Foster,Gray,Hall,Irving,James,King,Lewis,Martin,Nelson,Owen,Parker,Quinn,Ross,Scott,Turner,Underwood,Vernon,Walsh,Xavier,Young,Zhang,Adams,Bell,Cooper,Dixon';
    DECLARE fname VARCHAR(50);
    DECLARE lname VARCHAR(50);
    DECLARE dept_id INT;
    DECLARE desig_id INT;
    DECLARE comp_id INT;
    DECLARE salary_amt DECIMAL(10,2);
    DECLARE emp_types TEXT DEFAULT 'contract,part-time,full-time';
    DECLARE salary_types TEXT DEFAULT 'hourly,monthly,salary';
    DECLARE emp_type VARCHAR(20);
    DECLARE sal_type VARCHAR(20);
    DECLARE rate_val DECIMAL(10,2);
    
    WHILE i <= 500 DO
        SET fname = SUBSTRING_INDEX(SUBSTRING_INDEX(first_names, ',', ((i - 1) MOD 30) + 1), ',', -1);
        SET lname = SUBSTRING_INDEX(SUBSTRING_INDEX(last_names, ',', (i MOD 30) + 1), ',', -1);
        SET dept_id = IF(RAND() < 0.9, ((i - 1) MOD 500) + 1, NULL);
        SET desig_id = IF(RAND() < 0.9, ((i - 1) MOD 500) + 1, NULL);
        SET comp_id = ((i - 1) MOD 500) + 1;
        SET salary_amt = ROUND(30000 + (RAND() * 70000), 2);
        SET emp_type = SUBSTRING_INDEX(SUBSTRING_INDEX(emp_types, ',', ((i - 1) MOD 3) + 1), ',', -1);
        SET sal_type = SUBSTRING_INDEX(SUBSTRING_INDEX(salary_types, ',', ((i - 1) MOD 3) + 1), ',', -1);
        SET rate_val = IF(sal_type = 'hourly', ROUND(15 + (RAND() * 50), 2), ROUND(2000 + (RAND() * 6000), 2));
        
        INSERT INTO employees (employeeID, firstName, lastName, email, password, departmentID, designationID, companyID, salary, employee_type, salary_type, rate)
        VALUES (
            i,
            fname,
            lname,
            CONCAT(LOWER(fname), LOWER(lname), i, '@company', comp_id, '.com'),
            '$2y$12$guJVteqcoDIpwJdn1JlRYe6ORRDgU0riCsWkR63QEC52ZoHo5br9C', -- bcrypt hash
            dept_id,
            desig_id,
            comp_id,
            salary_amt,
            emp_type,
            sal_type,
            rate_val
        );
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertLeaveRequests` ()   BEGIN
    DECLARE i INT DEFAULT 12;
    DECLARE emp_id INT;
    DECLARE comp_id INT;
    DECLARE reasons TEXT DEFAULT 'Medical appointment,Family emergency,Conference attendance,Vacation,Personal day,Sick leave,Bereavement,Jury duty,Professional development,Family get-together';
    DECLARE reason_val TEXT;
    DECLARE leave_start TIMESTAMP;
    DECLARE leave_end TIMESTAMP;
    DECLARE statuses TEXT DEFAULT 'Pending,Approved,Denied';
    DECLARE status_val VARCHAR(20);
    DECLARE submission_dt DATE;
    DECLARE base_date DATE;
    
    WHILE i <= 500 DO
        SET emp_id = ((i - 1) MOD 500) + 1;
        SET comp_id = ((i - 1) MOD 500) + 1;
        SET reason_val = SUBSTRING_INDEX(SUBSTRING_INDEX(reasons, ',', ((i - 1) MOD 10) + 1), ',', -1);
        SET base_date = DATE_ADD(CURDATE(), INTERVAL FLOOR(RAND() * 60) - 30 DAY);
        SET leave_start = CONCAT(base_date, ' ', LPAD(8 + FLOOR(RAND() * 4), 2, '0'), ':00:00');
        SET leave_end = CONCAT(DATE_ADD(base_date, INTERVAL FLOOR(1 + RAND() * 5) DAY), ' ', LPAD(15 + FLOOR(RAND() * 4), 2, '0'), ':00:00');
        SET status_val = SUBSTRING_INDEX(SUBSTRING_INDEX(statuses, ',', ((i - 1) MOD 3) + 1), ',', -1);
        SET submission_dt = DATE_SUB(base_date, INTERVAL FLOOR(RAND() * 7) DAY);
        
        INSERT INTO leaverequests (requestID, employeeID, companyID, reason, leaveStart, leaveEnd, approvalStatus, submissionDate)
        VALUES (
            i,
            emp_id,
            comp_id,
            reason_val,
            leave_start,
            leave_end,
            status_val,
            submission_dt
        );
        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertPayroll` ()   BEGIN
    DECLARE i INT DEFAULT 2;
    DECLARE emp_id INT;
    DECLARE comp_id INT;
    DECLARE payment_amt DECIMAL(10,2);
    DECLARE statuses TEXT DEFAULT 'Processed,Unprocessed';
    DECLARE status_val VARCHAR(20);
    
    WHILE i <= 500 DO
        SET emp_id = ((i - 1) MOD 500) + 1;
        SET comp_id = ((i - 1) MOD 500) + 1;
        SET payment_amt = ROUND(1500 + (RAND() * 8500), 2);
        SET status_val = SUBSTRING_INDEX(SUBSTRING_INDEX(statuses, ',', IF(RAND() < 0.7, 1, 2)), ',', -1);
        
        INSERT INTO payroll (payrollID, employeeID, companyID, payment, status)
        VALUES (
            i,
            emp_id,
            comp_id,
            payment_amt,
            status_val
        );
        SET i = i + 1;
    END WHILE;
END$$

